const minifySvg = require('./lib/filter').minifySvg.bind(hexo)
hexo.config.minify = { svg: { enable: true, verbose: false, include: ['*.svg'], plugins: { cleanupIDs: false }, globOptions: { basename: true } } }
hexo.route.set('foo.svg', '<svg><rect x="1" y="2" width="3" height="4" id="a"/></svg>')
minifySvg().then(() => new Promise((resolve) => {
  let result = ''
  const output = hexo.route.get('foo.svg')
